{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Although the link between these factors and sport performance has been extensively examined in the literature, there remains a critical need for further research into their practical application and the role they play in mapping the psychological profiles of athletes [3-6]. Motivation and self-efficacy play important roles in optimizing athletes' performance [7,8]. However, there are still gaps in the measurement and applicability of these psychological factors [9].",
      "reason": "The manuscript describes the current state of knowledge regarding psychological factors in sports performance and identifies gaps in measurement and practical application."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "This study aims to conduct a meta-analysis focusing on the associations between psychological constructs and sport performance, as these relationships have been widely examined in existing literature [12,13]. ... This study aims to better understand the psychological dynamics of sport performance and develop strategies to optimize performance by mapping the psychological profiles of athletes.",
      "reason": "The manuscript explains the need for the review to better understand psychological dynamics and develop strategies to optimize performance."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Meta-analytic studies have demonstrated that these factors are critically linked to performance enhancement, yet further methodologically rigorous research is required to explore these associations in greater depth [22,23].",
      "reason": "The authors acknowledge existing meta-analytic studies and justify the need for the current review by citing the requirement for further methodologically rigorous research."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a meta-analysis of observational studies examining associations between psychological factors and performance, not a review of intervention effects with a specific mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not evaluating a complex intervention or delivery context that requires a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The hypotheses of the study are formulated as follows: Hypothesis 1: There is an association between psychological factors including motivation, self-efficacy, self-confidence, goal setting, attention, stress management, anxiety, openness to experience, neuroticism, agreeableness, extraversion, conscientiousness, personality traits, and emotional intelligence (EI) and sport performance. Hypothesis 2: Gender (male/female), athlete type (Elite/Non-elite), and sport type (Team/Individual) moderate the association between psychological factors and sport performance.",
      "reason": "The study explicitly states its objectives in the form of testable hypotheses, which serve as the research questions for the meta-analysis."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a meta-analysis of associations between psychological factors and sports performance, not a review of intervention effects (e.g., comparing an intervention group to a control group), so PICO is not the appropriate framework for these specific research questions."
    }
  ],
  "confidence": 100
}

